codeExamples.code:
terraform {
  required_version = ">= 1.6"
  required_providers {
    aws       = { source = "hashicorp/aws",       version = "~> 5.0" }
    snowflake = { source = "Snowflake-Labs/snowflake", version = "~> 0.94" }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "snowflake" {
  # account, user, and auth come from env vars (SNOWFLAKE_ACCOUNT, etc.)
}

# Raw-data lake bucket with versioning enabled
resource "aws_s3_bucket" "raw" {
  bucket = "acme-${var.env}-raw-data"
  tags   = { env = var.env, managed_by = "terraform" }
}

resource "aws_s3_bucket_versioning" "raw" {
  bucket = aws_s3_bucket.raw.id      # reference -> depends on the bucket
  versioning_configuration { status = "Enabled" }
}

# IAM role the loader assumes to write to the bucket
resource "aws_iam_role" "loader" {
  name = "acme-${var.env}-loader"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

# Snowflake warehouse for ETL compute
resource "snowflake_warehouse" "etl" {
  name           = upper("ACME_${var.env}_ETL_WH")
  warehouse_size = var.env == "prod" ? "MEDIUM" : "XSMALL"
  auto_suspend   = 60          # suspend after 60s idle to save cost
  auto_resume    = true
}

# --- variables.tf ---
variable "env" {
  description = "Deployment environment"
  type        = string
  validation {
    condition     = contains(["dev", "staging", "prod"], var.env)
    error_message = "env must be one of dev, staging, prod."
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "warehouse_size" {
  description = "Snowflake warehouse size override"
  type        = string
  default     = null   # null -> fall back to per-env default
}

# --- locals.tf ---
locals {
  name_prefix = "acme-${var.env}"
  wh_size     = coalesce(var.warehouse_size, var.env == "prod" ? "MEDIUM" : "XSMALL")
  common_tags = {
    env        = var.env
    managed_by = "terraform"
  }
}

# --- outputs.tf ---
output "raw_bucket_arn" {
  description = "ARN of the raw-data bucket"
  value       = aws_s3_bucket.raw.arn
}

output "loader_role_arn" {
  description = "ARN of the loader IAM role"
  value       = aws_iam_role.loader.arn
}

output "warehouse_name" {
  description = "Name of the ETL warehouse"
  value       = snowflake_warehouse.etl.name
}
